&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Antalya Milletvekilimiz Şerafettin Kılı&amp;ccedil;, TBMM&amp;rsquo;de d&amp;uuml;zenlediği basın toplantısında orman yangınlarından belediyeler &amp;uuml;zerindeki siyasi baskılara, hedeften sapan enflasyon rakamlarından &amp;ccedil;ift&amp;ccedil;inin maliyet krizine kadar g&amp;uuml;ndemdeki kritik gelişmeleri değerlendirdi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Kılı&amp;ccedil;, &amp;ldquo;T&amp;uuml;rkiye&amp;rsquo;nin ihtiyacı yeni siyasi transferler değil; yeni fabrikalar, yeni yatırımlar ve yeni istihdam alanlarıdır&amp;rdquo; a&amp;ccedil;ıklamasında bulundu.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;İklim Değişikliğini Hazırlıksızlığın Bahanesi H&amp;acirc;line Getiremeyiz&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Son bir hafta i&amp;ccedil;erisinde Antalya, Muğla ve Balıkesir başta olmak &amp;uuml;zere farklı illerde peş peşe &amp;ccedil;ıkan orman yangınlarına değinen Kılı&amp;ccedil;, yangınla m&amp;uuml;cadele eden ekiplere ve vatandaşlara ge&amp;ccedil;miş olsun dileklerini iletti. T&amp;uuml;rkiye&amp;rsquo;nin yaz ayları boyunca y&amp;uuml;ksek risk altında olduğunu hatırlatan Kılı&amp;ccedil;, şu uyarıları yaptı:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Yangınlarla m&amp;uuml;cadele; sadece u&amp;ccedil;ak ve helikopter sayısını tartışmak değildir. Risk haritalarının g&amp;uuml;ncellenmesi, orman i&amp;ccedil;i ve orman &amp;ccedil;evresindeki bakım &amp;ccedil;alışmalarının artırılması, erken uyarı sistemlerinin yaygınlaştırılması, enerji nakil hatlarından kaynaklanan risklerin azaltılması, yerel y&amp;ouml;netimlerle koordinasyonun g&amp;uuml;&amp;ccedil;lendirilmesi ve orman k&amp;ouml;yl&amp;uuml;s&amp;uuml;n&amp;uuml;n s&amp;uuml;recin aktif bir par&amp;ccedil;ası h&amp;acirc;line getirilmesi de en az yangına m&amp;uuml;dahale kadar &amp;ouml;nemlidir. T&amp;uuml;rkiye&amp;rsquo;nin artık felaketleri konuşan değil, felaketleri &amp;ouml;nleyen bir devlet kapasitesini inşa etmesi gerekmektedir.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Devlet Hi&amp;ccedil;bir Siyasi Partinin Arka Bah&amp;ccedil;esi Olmamalıdır&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Muhalefet belediyelerinin merkezi idareyle yaşadığı mali kısıtlamalar, kredi onayları ve idari engeller &amp;uuml;zerinden y&amp;uuml;r&amp;uuml;t&amp;uuml;len tartışmalara tepki g&amp;ouml;steren Kılı&amp;ccedil;, kamu kaynaklarının tarafsız y&amp;ouml;netilmesi gerektiğini vurguladı:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Bir belediyenin alacağı kaynak, başkanının rozetine g&amp;ouml;re mi belirlenecektir? Devletin imk&amp;acirc;nları, sadece iktidar partisine mensup belediyelerin kullanımına a&amp;ccedil;ık bir ayrıcalık mıdır? Devlet, hi&amp;ccedil;bir siyasi partinin arka bah&amp;ccedil;esi olmamalıdır; 86 milyon vatandaşın ortak evidir. Muhalefete tahamm&amp;uuml;l edemeyen, farklı siyasi g&amp;ouml;r&amp;uuml;şleri baskıyla hizaya getirmeye &amp;ccedil;alışan anlayışlar kısa vadede sonu&amp;ccedil; alabilir; fakat uzun vadede milletin devlete olan g&amp;uuml;venini zedeler. Siyasi rekabetin yolu baskı değil, hizmettir.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Hedefler Hayal, Rakamlar Ger&amp;ccedil;ek, Faturalar İse Milletin Cebindeki Kor!&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;A&amp;ccedil;ıklanan son enflasyon verilerini ve siyaset g&amp;uuml;ndemini meşgul eden transfer tartışmalarını değerlendiren Kılı&amp;ccedil;, hedeflerdeki sapmaya dikkat &amp;ccedil;ekti:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Milletin g&amp;uuml;ndemi; mutfaktaki yangın, pazardaki fiyatlar, işsizlik, hayat pahalılığı ve adalet beklentisidir. T&amp;Uuml;İK&amp;rsquo;e g&amp;ouml;re yıllık enflasyon %31,75 ger&amp;ccedil;ekleşmiştir. Bu rakam, 2026 yılı i&amp;ccedil;in ortaya konulan %16&amp;rsquo;lık hedefin neredeyse iki katıdır! Bir iş yerinde hedeften neredeyse %100 sapan bir m&amp;uuml;d&amp;uuml;r&amp;uuml;n başarısı sorgulanır, hatta g&amp;ouml;revine son verilir. Ama T&amp;uuml;rkiye&amp;rsquo;de hedefler tutmayınca hedefler değiştiriliyor; vatandaşın hayatı pahalılaşınca da bunun adına &amp;lsquo;başarı hik&amp;acirc;yesi&amp;rsquo; deniliyor. Biz Saadet Partisi olarak ilkesiz siyaset anlayışını doğru bulmuyoruz. Magazinlere konu olacak meselelerin, milletin asıl sorunlarını g&amp;ouml;r&amp;uuml;nmez hale getirmesini kabullenemeyiz!&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;TMO Alım Fiyatları Maliyet Artışlarının Gerisinde Kaldı&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Toprak Mahsulleri Ofisi (TMO) tarafından a&amp;ccedil;ıklanan buğday ve arpa alım fiyatlarını değerlendiren Kılı&amp;ccedil;, k&amp;acirc;ğıt &amp;uuml;zerindeki artışların y&amp;uuml;ksek girdi maliyetleri nedeniyle &amp;ccedil;ift&amp;ccedil;inin cebine yansımadığını aktardı:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;ldquo;Ekmeklik buğday ton başına 16 bin 350 TL, makarnalık buğday 17 bin TL, arpa ise 13 bin 520 TL olarak belirlenmiştir. Mazot, g&amp;uuml;bre, tohum, zirai ila&amp;ccedil;, sulama ve elektrik fiyatlarındaki artışlar, a&amp;ccedil;ıklanan alım fiyatlarının getirdiği farkı ertelemiş ve &amp;uuml;reticinin kazancının gerilemesine yol a&amp;ccedil;mıştır. Alım fiyatlarının hasat başladıktan sonra değil, ekim d&amp;ouml;neminden &amp;ouml;nce a&amp;ccedil;ıklanması gerekmektedir.&amp;rdquo;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:14.0pt&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Saadet Partisi&amp;rsquo;nin &amp;Ccedil;&amp;ouml;z&amp;uuml;m Re&amp;ccedil;etesi&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Milletvekili Şerafettin Kılı&amp;ccedil;, tarım ve ekonomi alanında derhal atılması gereken adımları şu şekilde sıraladı:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;TMO, piyasayı geriden takip eden değil, &amp;uuml;reticiyi koruyan etkin bir kuruma d&amp;ouml;n&amp;uuml;şt&amp;uuml;r&amp;uuml;lmelidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Fiyatlar belirlenirken &amp;ccedil;ift&amp;ccedil;inin maliyeti esas alınmalı ve &amp;uuml;zerine insanca yaşayabileceği bir k&amp;acirc;r payı eklenmelidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Mazot, g&amp;uuml;bre ve sulama destekleri artırılmalı, &amp;uuml;reticinin finansmana kolay erişimi sağlanmalıdır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;&amp;Ccedil;ift&amp;ccedil;iyi desteklemek bir kesime yardım değil; gıda g&amp;uuml;venliğini korumak, enflasyonla m&amp;uuml;cadele etmek ve kırsalın boşalmasını &amp;ouml;nlemektir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
